import{_ as r}from"./chunks/one-entry-per-language.nITitXw_.js";import{_ as t,H as a,f as o,i}from"./chunks/framework.B05LFaXs.js";const s="/cass-editor/docs/assets/framework-properties.CrshuSfD.png",n="/cass-editor/docs/assets/add-custom-framework-property.BKzY_Y13.png",l="/cass-editor/docs/assets/new-framework-property.CwcZNwiE.png",p="/cass-editor/docs/assets/limit-values.Bn4BSBAI.png",m="/cass-editor/docs/assets/limit-values-framework.DYZqVdrS.png",d="/cass-editor/docs/assets/framework-configuration.i1NWwl6w.png",_=JSON.parse('{"title":"Configuring Framework Properties","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/framework-properties/index.md","filePath":"authoring/framework-properties/README.md"}'),h={name:"authoring/framework-properties/index.md"};function g(c,e,u,f,y,w){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="configuring-framework-properties" tabindex="-1">Configuring Framework Properties <a class="header-anchor" href="#configuring-framework-properties" aria-label="Permalink to &quot;Configuring Framework Properties&quot;">​</a></h1><p>Framework properties are the values that can be added, edited, and deleted for framework objects. Minimal framework properties are <em><strong>id</strong></em>, <em><strong>name</strong></em>, and <em><strong>description</strong></em>. Properties added here will be displayed in the framework object at the top of the framework editor view.</p><p><img src="'+s+'" alt="Framework Configuration"></p><h2 id="property-fields" tabindex="-1">Property Fields <a class="header-anchor" href="#property-fields" aria-label="Permalink to &quot;Property Fields&quot;">​</a></h2><p>Certain property fields can be modified directly from the property list:</p><ul><li><em><strong>display label</strong></em> - label to be displayed in form inputs for that property</li><li><em><strong>description</strong></em> - description of this property</li><li><em><strong>display category</strong></em> - category (if any) under which the property is displayed in form inputs</li><li><em><strong>required</strong></em> - property required toggle</li><li><em><strong>display priority</strong></em> - priority in which the property is displayed in form inputs <ul><li><em>primary, secondary, or tertiary</em></li></ul></li></ul><p>At the framework level the following static rules apply:</p><ul><li>The <em><strong>id</strong></em> property is <em>required</em></li><li>The <em><strong>name</strong></em> property is <em>required</em> and has a display priority of <em>primary</em></li></ul><h2 id="custom-framework-properties" tabindex="-1">Custom Framework Properties <a class="header-anchor" href="#custom-framework-properties" aria-label="Permalink to &quot;Custom Framework Properties&quot;">​</a></h2><p>Custom properties can be added to a framework by clicking the <em>add custom framework property</em> button.</p><p><img src="'+n+'" alt="Add Custom Framework Property"></p><p>Once clicked, the <em>New Framework Property</em> dialogue window is displayed.</p><p><img src="'+l+'" alt="New Framework Property"></p><h3 id="custom-framework-property-fields" tabindex="-1">Custom Framework Property Fields <a class="header-anchor" href="#custom-framework-property-fields" aria-label="Permalink to &quot;Custom Framework Property Fields&quot;">​</a></h3><p>Several fields must be completed in order to add the new property. Some field options (such as <em>range/type: Text</em>) allow further customization of the property.</p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only editable at the time of property creation.</p></div><p>Custom properties in CaSS are stored as namespaced linked JSON-LD records. Because of this, all new properties must have a context. By default, all custom properties have the <strong>CaSS v4.0</strong> <a href="https://schema.cassproject.org/0.4/" target="_blank" rel="noreferrer">[schema]</a> context. However, it is also possible to modify this field to the following values:</p><ul><li><strong>CTDL-ASN</strong> - <a href="https://purl.org/ctdlasn/terms/" target="_blank" rel="noreferrer">https://purl.org/ctdlasn/terms/</a></li><li><strong>RDF Semantic Web Standards 1999</strong> - <a href="http://www.w3.org/1999/02/22-rdf-syntax-ns#" target="_blank" rel="noreferrer">http://www.w3.org/1999/02/22-rdf-syntax-ns#</a></li><li><strong>RDF Semantic Web Standards 2000</strong> - <a href="http://www.w3.org/2000/01/rdf-schema#" target="_blank" rel="noreferrer">http://www.w3.org/2000/01/rdf-schema#</a></li><li><strong>Key Based Authorization and Control</strong> - <a href="https://schema.cassproject.org/kbac/0.4/" target="_blank" rel="noreferrer">https://schema.cassproject.org/kbac/0.4/</a></li><li><strong>Eduworks v3.0</strong> - <a href="http://schema.eduworks.com/general/0.3/" target="_blank" rel="noreferrer">http://schema.eduworks.com/general/0.3/</a></li><li><strong>Schema.org</strong> - <a href="http://schema.org/" target="_blank" rel="noreferrer">http://schema.org/</a></li><li><strong>Achievements Standard Network</strong> - <a href="http://purl.org/ASN/schema/core/" target="_blank" rel="noreferrer">http://purl.org/ASN/schema/core/</a></li><li><strong>DCMI Elements v1.1</strong> - <a href="http://purl.org/dc/elements/1.1/" target="_blank" rel="noreferrer">http://purl.org/dc/elements/1.1/</a></li><li><strong>DCMI Terms</strong> - <a href="http://purl.org/dc/terms/" target="_blank" rel="noreferrer">http://purl.org/dc/terms/</a></li><li><strong>Gem v2.0</strong> - <a href="http://purl.org/gem/qualifiers/" target="_blank" rel="noreferrer">http://purl.org/gem/qualifiers/</a></li><li><strong>Relators Scheme</strong> - <a href="http://www.loc.gov/loc.terms/relators/" target="_blank" rel="noreferrer">http://www.loc.gov/loc.terms/relators/</a></li><li><strong>Simple Knowledge Organization System</strong> - <a href="http://www.w3.org/2004/02/skos/core#" target="_blank" rel="noreferrer">http://www.w3.org/2004/02/skos/core#</a></li></ul><p>It is highly recommended to accept the default for this field unless there is an actionable reason for not doing so.</p><h3 id="range-type" tabindex="-1">Range/Type <a class="header-anchor" href="#range-type" aria-label="Permalink to &quot;Range/Type&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only editable at the time of property creation.</p></div><p>The <em>range/type</em> field defines the property type. Certain range/types allow for further customization of the property. The following values are available for this field:</p><ul><li><strong>Lang-String</strong> - An RDF schema lang string as defined by <a href="http://www.w3.org/2000/01/rdf-schema#langString" target="_blank" rel="noreferrer">http://www.w3.org/2000/01/rdf-schema#langString</a>. <ul><li>Selecting this value opens the <em>One Entry Per Language</em> property field</li></ul></li><li><strong>URL</strong> - A schema.org URL as defined by <a href="http://schema.org/URL" target="_blank" rel="noreferrer">http://schema.org/URL</a></li><li><strong>Text</strong> - A schema.org Text (plain string) value as defined by <a href="http://schema.org/Text" target="_blank" rel="noreferrer">http://schema.org/Text</a><ul><li>Selecting this value opens the <em>Limit Values</em> property field</li></ul></li><li><strong>Date-Time</strong> - A w3.org dateTime value as defined by <a href="http://www.w3.org/2001/XMLSchema#dateTime" target="_blank" rel="noreferrer">http://www.w3.org/2001/XMLSchema#dateTime</a></li><li><strong>Date</strong> - A dublin core date value as defined by <a href="http://purl.org/dc/terms/date" target="_blank" rel="noreferrer">http://purl.org/dc/terms/date</a></li><li><strong>SKOS Concept</strong> - A CaSS concept value as defined by <a href="https://schema.cassproject.org/0.4/skos/Concept" target="_blank" rel="noreferrer">https://schema.cassproject.org/0.4/skos/Concept</a></li></ul><h3 id="display-priority" tabindex="-1">Display Priority <a class="header-anchor" href="#display-priority" aria-label="Permalink to &quot;Display Priority&quot;">​</a></h3><p>The priority in which the property is displayed in form inputs <em>(primary, secondary, or tertiary)</em>.</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h3><p>The property is required toggle.</p><h3 id="unique-property-identifier" tabindex="-1">Unique Property Identifier <a class="header-anchor" href="#unique-property-identifier" aria-label="Permalink to &quot;Unique Property Identifier&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only editable at the time of property creation.</p></div><p>The name of the property in the data record. Only alphanumerics are allowed.</p><h3 id="display-label" tabindex="-1">Display Label <a class="header-anchor" href="#display-label" aria-label="Permalink to &quot;Display Label&quot;">​</a></h3><p>The label to be displayed in form inputs for the property.</p><h3 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h3><p>The description of the property.</p><h3 id="display-category" tabindex="-1">Display Category <a class="header-anchor" href="#display-category" aria-label="Permalink to &quot;Display Category&quot;">​</a></h3><p>The category (if any) under which the property is displayed in form inputs.</p><h3 id="one-entry-per-language" tabindex="-1">One Entry Per Language <a class="header-anchor" href="#one-entry-per-language" aria-label="Permalink to &quot;One Entry Per Language&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=Lang-String</strong></em></p></div><p><img src="'+r+'" alt="One entry per language"></p><p>By toggling this field on, custom properties of the <em><strong>range/type Lang-String</strong></em> can be limited so that only a single entry can be made per language chosen.</p><h3 id="limit-values" tabindex="-1">Limit Values <a class="header-anchor" href="#limit-values" aria-label="Permalink to &quot;Limit Values&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is only available for <em><strong>range/type=Text</strong></em></p></div><p>When creating a custom property of <em><strong>range/type Text</strong></em>, you can limit the values allowed to the property. To do this, toggle the <em><strong>Limit Values</strong></em> field on and click the <em><strong>add</strong></em> button to begin managing the list of allowable values.</p><p><img src="'+p+'" alt="Limit Values"></p><p>For each entry in the limit values table, a <em><strong>display label</strong></em> and <em><strong>field value</strong></em> must be entered.</p><ul><li><em><strong>display label</strong></em> - the label displayed to the user when selecting the value</li><li><em><strong>field value</strong></em> - the recorded value when the value is selected by the user</li></ul><p><img src="'+m+'" alt="Limit Value Entries"></p><h2 id="applying-the-custom-framework-property" tabindex="-1">Applying the Custom Framework Property <a class="header-anchor" href="#applying-the-custom-framework-property" aria-label="Permalink to &quot;Applying the Custom Framework Property&quot;">​</a></h2><p>Once complete, the new property can be applied to the framework by clicking the <em><strong>apply new property</strong></em> in the lower right corner of the dialogue window.</p><h2 id="editing-deleting-custom-framework-properties" tabindex="-1">Editing/Deleting Custom Framework Properties <a class="header-anchor" href="#editing-deleting-custom-framework-properties" aria-label="Permalink to &quot;Editing/Deleting Custom Framework Properties&quot;">​</a></h2><p>Custom properties can be edited and deleted by selecting the appropriate action buttons to the right of the corresponding property entry in the <em><strong>Framework Properties</strong></em> list.</p><p><img src="'+d+'" alt="Delete Custom Properties"></p>',53)])])}const v=t(h,[["render",g]]);export{_ as __pageData,v as default};
